{"changes":[{"path":"header_merge.py","content":"from __future__ import annotations

from collections.abc import Mapping


def merge_headers(
    defaults: Mapping[str, str], overrides: Mapping[str, str]
) -> dict[str, str]:
    """Merge headers by name, preserving each name's first position."""

    merged: dict[str, tuple[str, str]] = {}
    for headers in (defaults, overrides):
        for name, value in headers.items():
            merged[name.casefold()] = (name, value)

    return dict(merged.values())
